package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="auditoria") public class AuditoriaEvento { @Id @GeneratedValue private UUID id; @Column(name="empresa_id") private UUID empresaId; @Column(name="usuario_id") private UUID usuarioId; private LocalDateTime fecha=LocalDateTime.now(); private String modulo; private String accion; private String entidad; @Column(name="registro_id") private UUID registroId; @Column(name="datos_nuevos") private String datosNuevos; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public UUID getUsuarioId(){return usuarioId;} public void setUsuarioId(UUID v){usuarioId=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} public String getModulo(){return modulo;} public void setModulo(String v){modulo=v;} public String getAccion(){return accion;} public void setAccion(String v){accion=v;} public String getEntidad(){return entidad;} public void setEntidad(String v){entidad=v;} public UUID getRegistroId(){return registroId;} public void setRegistroId(UUID v){registroId=v;} public String getDatosNuevos(){return datosNuevos;} public void setDatosNuevos(String v){datosNuevos=v;} }
